// BAD: Demonstrates improper Java API usage leading to vulnerabilities
// Scenario: SQL Injection via string concatenation and insecure cookie handling
import java.io.IOException;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class LoginServletBad extends HttpServlet {
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String user = request.getParameter("username"); // unvalidated/untrusted input
        String pass = request.getParameter("password"); // unvalidated/untrusted input

        // vulnerable: Building SQL query via string concatenation enables SQL injection
        String query = "SELECT id, role FROM users WHERE username = '" + user + "' AND password = '" + pass + "'";

        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/app", "appuser", "apppass");
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            if (rs.next()) {
                // vulnerable: Session fixation and missing security flags on cookie
                Cookie session = new Cookie("SESSIONID", request.getParameter("sid")); // accepts attacker-controlled SID
                session.setPath("/");
                // Missing: HttpOnly, Secure, SameSite flags
                response.addCookie(session);

                // vulnerable: Reflecting unsanitized input back to the client (XSS risk)
                response.getWriter().println("Welcome " + user + "!");
            } else {
                response.getWriter().println("Invalid credentials");
            }
        } catch (SQLException e) {
            // vulnerable: Leaking internal details to the client
            response.getWriter().println("Database error: " + e.getMessage());
        }
    }
}
***
/**
 * GOOD: Fixes SQL injection, cookie security, XSS, and error disclosure
 * - Uses PreparedStatement with parameter binding
 * - Uses server-generated session IDs and secure cookie attributes
 * - Encodes user-controlled output before reflecting
 * - Logs errors server-side without exposing internals
 */
import java.io.IOException;
import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class LoginServletGood extends HttpServlet {

    // Minimal HTML encoder to avoid XSS in this snippet (use a library like OWASP ESAPI in real apps)
    private String htmlEncode(String s) {
        if (s == null) return "";
        return s.replace("&", "&amp;")
                .replace("<", "&lt;")
                .replace(">", "&gt;")
                .replace("\"", "&quot;")
                .replace("'", "&#x27;");
    }

    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String user = request.getParameter("username");
        String pass = request.getParameter("password");

        // Basic input handling (consider additional validation/rate limiting as appropriate)
        if (user == null || pass == null) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Missing credentials");
            return;
        }

        String query = "SELECT id, role FROM users WHERE username = ? AND password = ?";

        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/app", "appuser", "apppass");
             PreparedStatement ps = conn.prepareStatement(query)) {

            // Use parameterized queries to prevent SQL injection
            ps.setString(1, user);
            ps.setString(2, pass); // In real apps, compare password hashes, not plaintext

            try (ResultSet rs = ps.executeQuery()) {
                if (rs.next()) {
                    // Use container-managed session; do not accept client-supplied session IDs
                    HttpSession httpSession = request.getSession(true); // generates new session if none
                    httpSession.invalidate(); // end any existing session to prevent fixation
                    HttpSession newSession = request.getSession(true); // create fresh session
                    newSession.setAttribute("userId", rs.getLong("id"));
                    newSession.setAttribute("role", rs.getString("role"));

                    // Ensure session cookie has secure attributes; many containers can be configured globally
                    // Below demonstrates adding a separate secure cookie if needed
                    Cookie secureFlag = new Cookie("SESSION_SECURE", "1");
                    secureFlag.setHttpOnly(true);
                    secureFlag.setSecure(request.isSecure()); // send only over HTTPS
                    secureFlag.setPath("/");
                    secureFlag.setMaxAge(-1);
                    secureFlag.setAttribute("SameSite", "Lax"); // SameSite protection
                    response.addCookie(secureFlag);

                    // Encode user-supplied data before reflecting
                    response.setContentType("text/html; charset=UTF-8");
                    response.getWriter().println("Welcome " + htmlEncode(user) + "!");
                } else {
                    response.sendError(HttpServletResponse.SC_UNAUTHORIZED, "Invalid credentials");
                }
            }
        } catch (SQLException e) {
            // Log internally; do not disclose details to client
            getServletContext().log("Database error during login", e);
            response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "An unexpected error occurred");
        }
    }
}

