// BAD: Improper use of Java API leading to SQL Injection and XXE
// This code builds SQL using string concatenation and parses XML with external entities enabled.
import java.io.*;
import java.sql.*;
import javax.xml.parsers.*;
import org.w3c.dom.*;
import org.xml.sax.InputSource;

public class InsecureExample {
    public User findUser(Connection conn, String username, String password, String xmlBody) throws Exception {
        // vulnerable: direct string concatenation into SQL allows SQL injection
        String sql = "SELECT id, username FROM users WHERE username = '" + username +
                     "' AND password = '" + password + "'";
        Statement st = conn.createStatement();
        ResultSet rs = st.executeQuery(sql);

        // vulnerable: insecure XML parser with external entities (XXE)
        DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
        // Common mistake: not disabling external entity processing
        DocumentBuilder db = dbf.newDocumentBuilder();
        Document doc = db.parse(new InputSource(new StringReader(xmlBody)));
        String note = doc.getDocumentElement().getTextContent();

        User u = null;
        if (rs.next()) {
            u = new User(rs.getInt("id"), rs.getString("username"));
            // Do something risky with parsed content
            System.out.println("User note: " + note);
        }
        rs.close();
        st.close();
        return u;
    }

    static class User {
        int id;
        String username;
        User(int id, String username) { this.id = id; this.username = username; }
    }
}
***
/*
 GOOD: Safe Java API usage
 - Use PreparedStatement with parameters to avoid SQL injection.
 - Use a secure XML parser by disabling external entities and DTDs to prevent XXE.
 - Also demonstrate safe resource handling with try-with-resources.
*/
import java.io.*;
import java.sql.*;
import javax.xml.parsers.*;
import org.w3c.dom.*;
import org.xml.sax.InputSource;
import org.xml.sax.SAXException;

public class SecureExample {
    public User findUser(Connection conn, String username, String password, String xmlBody) throws Exception {
        // Use parameterized query to prevent injection (fixes vulnerable pattern)
        String sql = "SELECT id, username FROM users WHERE username = ? AND password = ?";
        try (PreparedStatement ps = conn.prepareStatement(sql)) {
            ps.setString(1, username);
            ps.setString(2, password); // In real apps, store hashed passwords
            try (ResultSet rs = ps.executeQuery()) {
                // Secure XML parsing: disable external entities and DTDs (prevents XXE)
                DocumentBuilderFactory dbf = DocumentBuilderFactory.newInstance();
                dbf.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
                dbf.setFeature("http://xml.org/sax/features/external-general-entities", false);
                dbf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
                dbf.setFeature("http://apache.org/xml/features/nonvalidating/load-external-dtd", false);
                dbf.setXIncludeAware(false);
                dbf.setExpandEntityReferences(false);

                DocumentBuilder db = dbf.newDocumentBuilder();
                Document doc;
                try {
                    doc = db.parse(new InputSource(new StringReader(xmlBody)));
                } catch (SAXException e) {
                    // Handle malformed or disallowed XML safely
                    throw new IllegalArgumentException("Invalid XML payload", e);
                }

                String note = doc.getDocumentElement() != null
                    ? doc.getDocumentElement().getTextContent()
                    : "";

                if (rs.next()) {
                    User u = new User(rs.getInt("id"), rs.getString("username"));
                    System.out.println("User note: " + sanitizeForLog(note));
                    return u;
                }
                return null;
            }
        }
    }

    // Basic log sanitization to avoid log forging/control chars
    private String sanitizeForLog(String s) {
        return s == null ? "" : s.replaceAll("[\\r\\n\\t]", " ");
    }

    static class User {
        int id;
        String username;
        User(int id, String username) { this.id = id; this.username = username; }
    }
}

